const h = React.createElement;
const waterY = height * 0.48;
const bW = width * 0.13;
const bH = height * 0.44;
const dur = durationInFrames;
const clamp = {extrapolateLeft:'clamp',extrapolateRight:'clamp'};

const allSink = Math.floor(dur * 0.26);
const gP1End = Math.floor(dur * 0.38);
const gResume = Math.floor(dur * 0.44);
const gDeepEnd = Math.floor(dur * 0.62);

const offY = -bH - 50;
const stopY = waterY - bH;
const g30Y = waterY - bH * 0.7;
const g70Y = waterY - bH * 0.3;

const cyY = interpolate(frame, [0, allSink], [offY, stopY], clamp);
const viY = interpolate(frame, [4, Math.max(5, allSink + 4)], [offY, stopY], clamp);

const gA = interpolate(frame, [2, Math.max(3, allSink)], [offY, stopY], clamp);
const gB = interpolate(frame, [allSink, Math.max(allSink+1, gP1End)], [stopY, g30Y], clamp);
const gD = interpolate(frame, [gResume, Math.max(gResume+1, gDeepEnd)], [g30Y, g70Y], clamp);
const grY = frame <= allSink ? gA : frame <= gP1End ? gB : frame <= gResume ? g30Y : gD;

const tremor = frame > gResume && frame < gDeepEnd ? Math.sin(frame * 0.5) * 3 * interpolate(frame, [gResume, Math.max(gResume+1, gDeepEnd)], [1, 0], clamp) : 0;

const wOp = interpolate(frame, [Math.floor(dur*0.1), allSink], [0, 1], clamp);
const lOp = interpolate(frame, [allSink+5, Math.max(allSink+6, allSink+25)], [0, 1], clamp);
const glI = interpolate(frame, [gP1End, Math.max(gP1End+1, gDeepEnd)], [0, 1], clamp);
const pulse = 0.7 + 0.3 * Math.sin(frame * 0.12);

const wins = (topY, isG) => Array.from({length: 21}, (_, i) => {
  const r = Math.floor(i/3), c = i%3;
  const ww = bW*0.15, wh = bH*0.04;
  const wx = bW/4*(c+1) - ww/2;
  const wy = bH/8*(r+1) - wh/2;
  const uw = (topY + wy) > waterY;
  return h('div', {key: i, style: {
    position:'absolute', left:wx, top:wy, width:ww, height:wh,
    backgroundColor: isG && uw ? D.green : D.white,
    opacity: isG && uw ? 0.85*pulse : 0.2, borderRadius:2
  }});
});

const mkB = (x, y, col, isG, k, xOff) => h('div', {key:k, style: {
  position:'absolute', left: x - bW/2 + (xOff||0), top:y, width:bW, height:bH, zIndex:5
}},
  h('div', {style: {
    position:'absolute', left:'12%', bottom:'100%', width:'76%', height:bH*0.04,
    backgroundColor:col, opacity:0.9, borderRadius:'3px 3px 0 0'
  }}),
  h('div', {style: {
    width:'100%', height:'100%', backgroundColor:col, opacity:0.75,
    borderRadius:'2px 2px 0 0'
  }}, ...wins(y, isG))
);

const uwH = Math.max(0, grY + bH - waterY);

return h('div', {style:{position:'absolute', inset:0, backgroundColor:D.bg, overflow:'hidden'}},
  h('div', {style:{
    position:'absolute', inset:0, opacity:D.dot_grid_opacity*0.3,
    backgroundImage:'radial-gradient(circle,'+D.text_dim+' 1px,transparent 1px)',
    backgroundSize:D.dot_grid_spacing+'px '+D.dot_grid_spacing+'px'
  }}),
  mkB(width*0.22, cyY, D.cyan, false, 'c', 0),
  mkB(width*0.50, grY, D.green, true, 'g', tremor),
  mkB(width*0.78, viY, D.violet, false, 'v', 0),
  h('div', {style:{
    position:'absolute', left:0, top:waterY, width:width, height:height-waterY,
    backgroundColor:D.bg, opacity:wOp*0.78, zIndex:8
  }}),
  h('div', {style:{
    position:'absolute', left:0, top:waterY, width:width, height:height-waterY,
    backgroundColor:D.cyan, opacity:wOp*0.06, zIndex:9
  }}),
  uwH > 0 ? h('div', {style:{
    position:'absolute', left:width*0.5-bW*0.7, top:waterY+5,
    width:bW*1.4, height:uwH+25,
    backgroundColor:D.green, opacity:glI*0.22*pulse,
    filter:'blur(28px)', borderRadius:'40%', zIndex:10
  }}) : null,
  h('div', {style:{
    position:'absolute', left:0, top:waterY-2, width:width, height:4,
    backgroundColor:D.cyan, opacity:wOp*0.9, zIndex:15,
    boxShadow:'0 0 12px '+D.cyan+',0 0 35px '+D.cyan
  }}),
  ...Array.from({length:3}, (_,i) => h('div', {key:'r'+i, style:{
    position:'absolute', left:Math.sin(frame*0.04+i*2)*12,
    top:waterY+18+i*22, width:width, height:1,
    backgroundColor:D.cyan, opacity:wOp*(0.18-i*0.05), zIndex:11
  }})),
  h('div', {style:{
    position:'absolute', left:width*0.57, top:waterY-38, opacity:lOp, zIndex:20,
    fontFamily:D.font_mono, fontSize:Math.max(14, width*0.015),
    color:D.cyan, letterSpacing:3, whiteSpace:'nowrap',
    textShadow:'0 0 8px '+D.cyan
  }}, 'GENERAL AVAILABILITY'),
  h('div', {style:{
    position:'absolute', left:width*0.64, top:waterY-10,
    width:2, height:10, backgroundColor:D.cyan, opacity:lOp*0.6, zIndex:20
  }})
);
